from pathlib import Path
import subprocess,json,hashlib,datetime
out=Path('/workspace/.cloud-build/flow-b6-validation');results=[]
variants=['base','mutex','payload','records','system']
for r in range(5):
    order=variants[r:]+variants[:r]
    if r%2: order=list(reversed(order))
    for v in order:
        binary=Path('/workspace/.cloud-build')/('flow-b6-'+v+'-build')/'flow_microbenchmark'
        p=subprocess.run([str(binary)],capture_output=True,text=True,timeout=30)
        row={'round':r,'variant':v,'command':[str(binary)],'sha256':hashlib.sha256(binary.read_bytes()).hexdigest(),'exit':p.returncode,'stdout':p.stdout,'stderr':p.stderr}
        (out/f'{v}-micro-{r}.txt').write_text(p.stdout+p.stderr);results.append(row)
        if p.returncode: raise RuntimeError(row)
    binary=Path('/workspace/.cloud-build/flow-b6-base-build/flow_mechanism_benchmark')
    p=subprocess.run([str(binary)],capture_output=True,text=True,timeout=30)
    row={'round':r,'variant':'mechanism','sha256':hashlib.sha256(binary.read_bytes()).hexdigest(),'exit':p.returncode,'stdout':p.stdout,'stderr':p.stderr}
    (out/f'mechanism-{r}.txt').write_text(p.stdout+p.stderr);results.append(row)
    if p.returncode: raise RuntimeError(row)
(out/'experiment-runs.json').write_text(json.dumps(results,indent=2)+'\n')
print('Five rounds of five integrated variants and isolated mechanism measurements completed.')

