from pathlib import Path
import subprocess,json,hashlib,datetime
root=Path('/workspace/.cloud-build');out=root/'flow-b6-validation';results=[]
sets=[ [('before-micro',root/'flow-b6-base-build/flow_microbenchmark'),('small-micro',root/'flow-b6-small-build/flow_microbenchmark'),('current-micro',root/'flow-b6-release/flow_microbenchmark')], [('before-payload',out/'before-payload'),('small-payload',out/'small-payload'),('current-payload',root/'flow-b6-release/flow_payload_benchmark')], [('before-diagnostics',out/'before-diagnostics'),('current-diagnostics',root/'flow-b6-release/flow_diagnostics_benchmark')], [('before-gpu-gap',out/'before-gpu-gap'),('current-gpu-gap',root/'flow-b6-release/flow_gpu_gap_benchmark')], [('current-mechanism',root/'flow-b6-release/flow_mechanism_benchmark')]]
for r in range(5):
    for group in sets:
        order=group[r%len(group):]+group[:r%len(group)]
        if r%2: order=list(reversed(order))
        for name,binary in order:
            p=subprocess.run([str(binary)],capture_output=True,text=True,timeout=60)
            row={'round':r,'variant':name,'command':[str(binary)],'sha256':hashlib.sha256(binary.read_bytes()).hexdigest(),'exit':p.returncode,'stdout':p.stdout,'stderr':p.stderr}
            (out/f'final-{name}-{r}.txt').write_text(p.stdout+p.stderr);results.append(row)
            if p.returncode:
                (out/'final-runs.json').write_text(json.dumps(results,indent=2)+'\n');raise RuntimeError(row)
    print(f'round {r+1}/5 complete',flush=True)
(out/'final-runs.json').write_text(json.dumps({'measured_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'runs':results},indent=2)+'\n')
